<?php

declare(strict_types=1);

namespace Psalm\Tests;

use Override;
use Psalm\Tests\Traits\InvalidCodeAnalysisTestTrait;
use Psalm\Tests\Traits\ValidCodeAnalysisTestTrait;

use function escapeshellarg;
use function exec;
use function implode;

use const PHP_BINARY;

/**
 * The Hack conformance fixtures, transpiled to PHP: Psalm must give each the
 * verdict HHVM gives the original (checked by HackConformanceTest).
 *
 * Generated by bin/hack-conformance/transpile.php from the Hack fixtures in
 * bin/hack-conformance/fixtures/. Do not edit: edit the fixtures and regenerate.
 */
final class HackConformanceTranspiledTest extends TestCase
{
    use InvalidCodeAnalysisTestTrait;
    use ValidCodeAnalysisTestTrait;

    /**
     * Transpiles the fixtures again before any case runs, so that every case
     * fails if this file was not regenerated after a fixture (or the
     * transpiler) changed. Transpiling needs HHVM's parser: where it cannot
     * run (exit code 3), the committed cases run as they are, and
     * HackConformanceTest::testTranspiledSuiteIsUpToDate skips.
     */
    #[Override]
    public static function setUpBeforeClass(): void
    {
        parent::setUpBeforeClass();

        $output = [];
        $exitCode = 0;
        exec(
            escapeshellarg(PHP_BINARY) . ' '
                . escapeshellarg(__DIR__ . '/../bin/hack-conformance/transpile.php') . ' --check 2>&1',
            $output,
            $exitCode,
        );

        if ($exitCode !== 0 && $exitCode !== 3) {
            /** @var list<string> $output */
            self::fail(implode("\n", $output));
        }
    }

    /**
     * @psalm-pure
     */
    #[Override]
    public function providerValidCodeParse(): iterable
    {
        return [
            'contexts/inout_local_write' => [
                // writing an `inout` parameter is not an effect, and passing a local `inout` to
                // such a function from a `[]` context is fine: the write lands in the caller's own
                // local. Psalm charges a by-reference argument for what it is, nothing for a local.
                'code' => '<?php
                    /** @psalm-capabilities read-props|write-refs */
                    function set_ref(int &$x): void { $x = 1; }

                    /** @psalm-capabilities read-props */
                    function passes_local(): int {
                        $x = 0;
                        set_ref($x);
                        return $x;
                    }

                    /** @psalm-capabilities read-props|write-refs */
                    function passes_own_inout(int &$x): void { set_ref($x); }',
                'assertions' => [],
                'ignored_issues' => [],
                'php_version' => '8.3',
            ],
            'contexts/named_context_constant' => [
                // a class may name a context once (`const ctx Storage = [...]`) and functions
                // refer to it (`[Repo::Storage]`). Psalm spells the alias with `@psalm-type`
                // (and `@psalm-import-type` from other classes) inside `@psalm-capabilities`.
                // The effect is IO because Hack's parse-level property-write check cannot
                // resolve a context constant.
                'code' => '<?php
                    /** @psalm-type Storage = impure */
                    final class Repo {
                        /** @psalm-capabilities Storage|read-props */
                        public function save(): void { echo "saved"; }
                    }

                    /** @psalm-import-type Storage from Repo */
                    final class Service {
                        /** @psalm-capabilities Storage|read-props */
                        public function run(Repo $r): void { $r->save(); }
                    }',
                'assertions' => [],
                'ignored_issues' => [],
                'php_version' => '8.3',
            ],
            'polymorphic_contexts/context_constant_default' => [
                // an abstract context constant with a default is synthesized for the first
                // concrete class that does not define it: the default of Psalm's purity template,
                // `C(...)`, binds C for subclasses without an `@extends` argument.
                'code' => '<?php
                    /** @psalm-purity-template C(read-props) <= read-props|write-this-props|write-props */
                    abstract class Doer {
                        /**
                         * @psalm-capabilities read-props
                         * @psalm-purity-from-template C
                         */
                        public function run(): int { return 1; }
                    }

                    final class DefaultDoer extends Doer {}

                    /** @extends Doer[read-props|write-this-props|write-props] */
                    final class MutatingDoer extends Doer {}

                    /** @psalm-capabilities read-props */
                    function useDefault(DefaultDoer $d): int { return $d->run(); }

                    /** @psalm-capabilities read-props|write-this-props|write-props */
                    function useMutating(MutatingDoer $d): int { return $d->run(); }',
