                'code' => '<?php
                    /** @psalm-capabilities read-props|write-this-props|write-props */
                    function do_write_props(): void {}

                    /** @psalm-purity-template read-props|write-this-props|write-props <= C */
                    abstract class Doer {
                        /**
                         * @psalm-capabilities read-props
                         * @psalm-purity-from-template C
                         */
                        public function run(): void { do_write_props(); }
                    }

                    /** @extends Doer[impure] */
                    final class IoDoer extends Doer {}

