    /**
     * @psalm-pure
     */
    #[Override]
    public function providerInvalidCodeParse(): iterable
    {
        return [
            'contexts/dynamic_new_context' => [
                // `new $c()` on a classname checks the constructor of that class. Psalm checks
                // the constructor of the class a class-string stands for, and treats an unknown
                // class as impure.
                'code' => '<?php
                    final class Noisy {
                        /** @psalm-impure */
                        public function __construct() { echo "created"; }
                    }

                    /**
                     * @psalm-capabilities read-props
                     * @param class-string<Noisy> $c
                     */
                    function make(string $c): Noisy { return new $c(); }',
                'error_message' => 'ImpureMethodCall',
                'error_levels' => [],
                'php_version' => '8.3',
            ],
            'contexts/function_pointer_context' => [
                // a function pointer carries the context of the function it points to, so
                // calling it needs the same capabilities as calling the function. Psalm's
                // first-class callables carry their capabilities the same way.
                'code' => '<?php
                    /** @psalm-impure */
                    function roll(): int { return 4; }

                    /** @psalm-capabilities read-props */
                    function pure_roll(): int {
                        $r = roll(...);
                        return $r();
                    }',
                'error_message' => 'ImpureFunctionCall',
                'error_levels' => [],
                'php_version' => '8.3',
            ],
            'contexts/readonly_global_getter_leak' => [
                // a readonly value stays readonly through a function that returns it, so the
                // caller cannot mutate it either. Psalm flags the results of callees that may
                // read globals as reached from global state.
                'code' => '<?php
                    final class Box {
                        public int $x = 0;

                        public static ?Box $g = null;
                    }

                    /** @psalm-capabilities read-props|read-globals */
                    function get(): ?Box { return Box::$g; }

                    /** @psalm-capabilities read-props|write-this-props|write-props|read-globals */
                    function leak(): void {
                        $b = get();
                        if ($b !== null) { $b->x = 1; }
                    }',
                'error_message' => 'ImpurePropertyAssignment',
                'error_levels' => [],
                'php_version' => '8.3',
            ],
            'contexts/readonly_global_leak' => [
                // `read_globals` only hands out `readonly` views of static properties, so a
                // function with read_globals and write_props still cannot mutate an object it
                // reached through a static property. Psalm tracks the same thing with the
                // from_global_state flag: mutating such a value needs write-globals.
                'code' => '<?php
                    final class Box {
                        public int $x = 0;

                        public static ?Box $g = null;
                    }

                    /** @psalm-capabilities read-props|write-this-props|write-props|read-globals */
                    function leak(): void {
                        $b = Box::$g;
                        if ($b !== null) { $b->x = 1; }
                    }',
                'error_message' => 'ImpurePropertyAssignment',
                'error_levels' => [],
                'php_version' => '8.3',
            ],
            'contexts/throw_impure_constructor' => [
