                        public function __construct() { echo "created"; parent::__construct("x"); }
                    }

                    /** @psalm-capabilities read-props */
                    function fail(): int { throw new MyException(); }',
                'error_message' => 'ImpureMethodCall',
                'error_levels' => [],
                'php_version' => '8.3',
            ],
            'polymorphic_contexts/context_constant_bound' => [
                // `super [write_props]` caps what a subclass may require: the upper bound of
